draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // question mark
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 20, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 10);
  ctx.lineTo(W/2 + 50, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 20, 10, 0, Math.PI);
  ctx.stroke();

  // waves of thought
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100 + 20*Math.sin(t));
  ctx.lineTo(W/2 - 80, H/2 + 100 + 20*Math.sin(t + 0.1));
  ctx.lineTo(W/2 - 60, H/2 + 100 + 20*Math.sin(t + 0.2));
  ctx.lineTo(W/2 - 40, H/2 + 100 + 20*Math.sin(t + 0.3));
  ctx.lineTo(W/2 - 20, H/2 + 100 + 20*Math.sin(t + 0.4));
  ctx.lineTo(W/2, H/2 + 100 + 20*Math.sin(t + 0.5));
  ctx.lineTo(W/2 + 20, H/2 + 100 + 20*Math.sin(t + 0.6));
  ctx.lineTo(W/2 + 40, H/2 + 100 + 20*Math.sin(t + 0.7));
  ctx.lineTo(W/2 + 60, H/2 + 100 + 20*Math.sin(t + 0.8));
  ctx.lineTo(W/2 + 80, H/2 + 100 + 20*Math.sin(t + 0.9));
  ctx.stroke();

  ctx.restore();
}
